-- Disposable/rolled-back fixtures. Never use genuine employees or wallets.
begin;
insert into public.tenants(tenant_id,business_name) values('e1111111-1111-4111-8111-111111111111','Payroll SQL fixture A'),('f1111111-1111-4111-8111-111111111111','Payroll SQL fixture B');
insert into auth.users(id,email,is_anonymous) values('e2222222-2222-4222-8222-222222222222','payroll-sql-a@example.invalid',false),('f2222222-2222-4222-8222-222222222222','payroll-sql-b@example.invalid',false);
insert into public.user_profiles(user_id,tenant_id,email) values('e2222222-2222-4222-8222-222222222222','e1111111-1111-4111-8111-111111111111','payroll-sql-a@example.invalid'),('f2222222-2222-4222-8222-222222222222','f1111111-1111-4111-8111-111111111111','payroll-sql-b@example.invalid');
insert into public.roles(tenant_id,role_id,name) values('e1111111-1111-4111-8111-111111111111','e4444444-4444-4444-8444-444444444444','OWNER'),('f1111111-1111-4111-8111-111111111111','f4444444-4444-4444-8444-444444444444','OWNER');
insert into public.role_permissions select r.tenant_id,r.role_id,p.permission_id from public.roles r cross join public.permissions p where r.tenant_id in ('e1111111-1111-4111-8111-111111111111','f1111111-1111-4111-8111-111111111111');
insert into public.user_roles values('e1111111-1111-4111-8111-111111111111','e2222222-2222-4222-8222-222222222222','e4444444-4444-4444-8444-444444444444'),('f1111111-1111-4111-8111-111111111111','f2222222-2222-4222-8222-222222222222','f4444444-4444-4444-8444-444444444444');
create temporary table payroll_context(eid uuid,eid2 uuid,oid uuid,oid2 uuid,cash uuid,bank uuid,advance uuid,adjustment uuid,payment uuid,request uuid,body jsonb,transit uuid);
insert into payroll_context(cash,bank,request) select (select wallet_id from public.wallets where tenant_id='e1111111-1111-4111-8111-111111111111' and type='cash'),(select wallet_id from public.wallets where tenant_id='e1111111-1111-4111-8111-111111111111' and type='dealership'),gen_random_uuid();
grant all on payroll_context to authenticated;
create function pg_temp.payroll_check(ok boolean,msg text) returns void language plpgsql as $$ begin if ok is not true then raise exception 'FAIL: %',msg; end if; end $$;
create function pg_temp.payroll_fails(q text,expected text) returns void language plpgsql as $$ begin
 begin execute q; exception when others then if position(lower(expected) in lower(sqlerrm))=0 then raise exception 'Expected %; got %',expected,sqlerrm; end if; return; end;
 raise exception 'Expected rejection: %',expected; end $$;
grant execute on function pg_temp.payroll_check(boolean,text),pg_temp.payroll_fails(text,text) to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','e2222222-2222-4222-8222-222222222222',true);
update payroll_context set body='{"name":"Payroll Driver Mirpur","phones":[{"phone":"01700000031","is_primary":true}],"business_unit":"truck_business","employee_type_name":"Driver","terms":{"monthly_salary":28000,"effective_from":"2025-02-10","is_active":true}}';
update payroll_context set eid=(public.save_employee(body,request)->>'employee_id')::uuid;
select pg_temp.payroll_check(public.save_employee(body,request)->>'employee_id'=eid::text,'same-key profile retry') from payroll_context;
select pg_temp.payroll_fails($q$select public.save_employee(body||'{"name":"changed"}',request) from payroll_context$q$,'different details');
select public.save_employee(body||jsonb_build_object('employee_id',eid,'revision',1,'terms',jsonb_build_object('effective_from','2025-02-20','monthly_salary',56000,'is_active',true,'reason','Salary revision')),gen_random_uuid()) from payroll_context;
select public.save_employee(body||jsonb_build_object('employee_id',eid,'revision',2,'terms',jsonb_build_object('effective_from','2025-02-25','monthly_salary',56000,'is_active',false,'reason','Employment ended')),gen_random_uuid()) from payroll_context;
select public.save_employee(body||jsonb_build_object('employee_id',eid,'revision',3,'terms',jsonb_build_object('effective_from','2025-03-10','monthly_salary',31000,'is_active',true,'reason','Reactivated')),gen_random_uuid()) from payroll_context;
update payroll_context set eid2=(public.save_employee('{"name":"Payroll Helper Uttara","phones":[{"phone":"01700000032","is_primary":true}],"business_unit":"truck_business","employee_type_name":"Helper","terms":{"monthly_salary":14000,"effective_from":"2025-02-01","is_active":true}}',gen_random_uuid())->>'employee_id')::uuid;
select public.payroll_operation('{"action":"prepare","period":"2025-02-01"}',gen_random_uuid());
update payroll_context set oid=(public.get_employee_periods(eid)->'entries'->0->>'obligation_id')::uuid,oid2=(public.get_employee_periods(eid2)->'entries'->0->>'obligation_id')::uuid;
select pg_temp.payroll_check((public.get_employee_periods(eid)->'entries'->0->>'base_amount')::numeric=20000,'joining, salary revision and leaving prorate correctly') from payroll_context;
select pg_temp.payroll_check((public.payroll_operation('{"action":"prepare","period":"2025-02-01"}',gen_random_uuid())->>'prepared')::int=0,'preparation is repeat-safe');
select public.payroll_operation(jsonb_build_object('action','prepare','period','2025-03-01','employee_id',eid),gen_random_uuid()) from payroll_context;
select pg_temp.payroll_check((public.get_employee_periods(eid)->'entries'->0->>'base_amount')::numeric=22000,'reactivation leaves inactive days unpaid') from payroll_context;
select public.payroll_operation(jsonb_build_object('action','prepare','period','2025-01-01','employee_id',eid),gen_random_uuid()) from payroll_context;
select pg_temp.payroll_check((public.get_employee_periods(eid)->'entries'->2->>'base_amount')::numeric=0,'before joining is unpaid') from payroll_context;
select pg_temp.payroll_fails($q$select public.save_employee(body||jsonb_build_object('employee_id',eid,'revision',4,'terms',jsonb_build_object('effective_from','2025-03-20','monthly_salary',50000,'is_active',true,'reason','Retroactive change')),gen_random_uuid()) from payroll_context$q$,'Prepared payroll is preserved');
select pg_temp.payroll_fails($q$select public.save_employee(body||jsonb_build_object('employee_id',eid,'revision',1),gen_random_uuid()) from payroll_context$q$,'Employee changed');
select pg_temp.payroll_fails($q$select public.save_employee((body-'terms')||jsonb_build_object('employee_id',eid,'revision',4,'phones','[{"phone":"bad","is_primary":true}]'::jsonb),gen_random_uuid()) from payroll_context$q$,'check constraint');
select pg_temp.payroll_check(public.get_employee_profile(eid)->'employee'->>'primary_phone'='01700000031','failed update keeps phones') from payroll_context;

update payroll_context set body=jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',eid,'kind','advance','payment_date',current_date,'description','Salary advance','payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',3000))))),request=gen_random_uuid();
update payroll_context set advance=(public.payroll_operation(body,request)->'payment_ids'->>0)::uuid;
select pg_temp.payroll_check(public.payroll_operation(body,request)->'payment_ids'->>0=advance::text,'same-key advance retry') from payroll_context;
select pg_temp.payroll_check((public.get_employee_profile(eid)->'advances'->0->>'remaining')::numeric=3000,'advance is receivable') from payroll_context;
select public.payroll_operation(jsonb_build_object('action','adjust','obligation_id',oid,'kind','bonus','amount',1000,'reason','Performance bonus'),gen_random_uuid()) from payroll_context;
select public.payroll_operation(jsonb_build_object('action','adjust','obligation_id',oid,'kind','deduction','amount',500,'reason','Unpaid adjustment'),gen_random_uuid()) from payroll_context;
update payroll_context set adjustment=(public.payroll_operation(jsonb_build_object('action','adjust','obligation_id',oid,'kind','advance_repayment','amount',1000,'advance_id',advance,'reason','Apply advance'),gen_random_uuid())->>'adjustment_id')::uuid;
select pg_temp.payroll_check((public.get_employee_periods(eid)->'entries'->1->'balance'->>'earned')::numeric=20500 and (public.get_employee_periods(eid)->'entries'->1->'balance'->>'outstanding')::numeric=19500,'advance reduces cash due without reducing earned salary') from payroll_context;
select pg_temp.payroll_fails($q$select public.payroll_operation(jsonb_build_object('action','adjust','obligation_id',oid,'kind','advance_repayment','amount',2500,'advance_id',advance,'reason','Over-recovery'),gen_random_uuid()) from payroll_context$q$,'outstanding advance');
select pg_temp.payroll_fails($q$select public.payroll_operation(jsonb_build_object('action','reverse_payment','payment_id',advance,'payment_date',current_date,'reason','Refund'),gen_random_uuid()) from payroll_context$q$,'repayments');

update payroll_context set body=jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',eid,'obligation_id',oid,'kind','salary','payment_date',current_date,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',5000),jsonb_build_object('wallet_id',bank,'amount',3000,'reference','PAYROLL-SPLIT'))))),request=gen_random_uuid();
update payroll_context set payment=(public.payroll_operation(body,request)->'payment_ids'->>0)::uuid;
select pg_temp.payroll_check(public.payroll_operation(body,request)->'payment_ids'->>0=payment::text,'salary retry is exact-once') from payroll_context;
select pg_temp.payroll_check((public.get_employee_periods(eid)->'entries'->1->'balance'->>'outstanding')::numeric=11500,'partial multi-wallet salary balance') from payroll_context;
select pg_temp.payroll_fails($q$select public.payroll_operation(jsonb_set(body,'{items,0,payments,0,amount}','12000'),gen_random_uuid()) from payroll_context$q$,'exceeds outstanding');
select pg_temp.payroll_fails($q$select public.payroll_operation(jsonb_set(body,'{items,0,payments,0,amount}','1.001'),gen_random_uuid()) from payroll_context$q$,'two decimal');
select pg_temp.payroll_fails($q$select public.payroll_operation(jsonb_build_object('action','adjust','obligation_id',oid,'kind','deduction','amount',12000,'reason','Below settled'),gen_random_uuid()) from payroll_context$q$,'below amounts already settled');
-- Multiple payments settle the same monthly obligation.
select public.payroll_operation(jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',eid,'obligation_id',oid,'kind','salary','payment_date',current_date,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',11500))))),gen_random_uuid()) from payroll_context;
select pg_temp.payroll_check((public.get_employee_periods(eid)->'entries'->1->'balance'->>'status')='paid','multiple payments settle salary') from payroll_context;
select public.payroll_operation(jsonb_build_object('action','reverse_payment','payment_id',payment,'payment_date',current_date,'reason','Employee returned incorrect payout'),gen_random_uuid()) from payroll_context;
select pg_temp.payroll_check((public.get_employee_periods(eid)->'entries'->1->'balance'->>'outstanding')::numeric=8000,'payment reversal restores due') from payroll_context;
select pg_temp.payroll_fails($q$select public.payroll_operation(jsonb_build_object('action','reverse_payment','payment_id',payment,'payment_date',current_date,'reason','Twice'),gen_random_uuid()) from payroll_context$q$,'already been reversed');
select public.payroll_operation(jsonb_build_object('action','reverse_adjustment','adjustment_id',adjustment,'reason','Unapply advance'),gen_random_uuid()) from payroll_context;
select pg_temp.payroll_check((public.get_employee_profile(eid)->'advances'->0->>'remaining')::numeric=3000,'adjustment reversal releases advance') from payroll_context;
-- Bulk salary either commits completely or rolls back completely.
update payroll_context set body=jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',eid,'obligation_id',oid,'kind','salary','payment_date',current_date,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',9000))),jsonb_build_object('employee_id',eid2,'obligation_id',oid2,'kind','salary','payment_date',current_date,'payments',jsonb_build_array(jsonb_build_object('wallet_id',bank,'amount',14001)))));
select pg_temp.payroll_fails($q$select public.payroll_operation(body,gen_random_uuid()) from payroll_context$q$,'exceeds outstanding');
select pg_temp.payroll_check((public.get_employee_periods(eid)->'entries'->1->'balance'->>'outstanding')::numeric=9000,'failed bulk rolls back first employee') from payroll_context;
select public.payroll_operation(jsonb_set(body,'{items,1,payments,0,amount}','14000'),gen_random_uuid()) from payroll_context;

select pg_temp.payroll_check((public.get_employee_directory('{"search":"driver mirpur, missing"}','2025-02-01')->>'total')::int=1,'AND/OR employee search');
select pg_temp.payroll_check((public.get_employee_directory('{"payment":"paid","sort":"due_desc"}','2025-02-01',0,1)->>'total')::int=2,'filtered total independent of page');
select pg_temp.payroll_check((public.get_employee_activity('{"search":"PAYROLL-SPLIT"}')->>'total')::int=2,'wallet reference search includes original and refund');
reset role;
-- Named driver/helper payments must not be charged again at trip closure.
insert into public.trucks(tenant_id,truck_id,name,serial_no,capacity,size,status) values('e1111111-1111-4111-8111-111111111111','e3333333-3333-4333-8333-333333333333','Payroll truck','PAYROLL-SQL',10,'small','idle');
set local role authenticated;
update payroll_context set transit=(public.create_custom_transit(jsonb_build_object('truck_id','e3333333-3333-4333-8333-333333333333','fee',0,'client_name','Payroll trip fixture'))->>'transit_id')::uuid;
select public.save_transit_costs(transit,'{"driver_cost":500,"helper_cost":200,"oil_cost":100,"others_cost":0}',1) from payroll_context;
select public.payroll_operation(jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',eid,'kind','trips','trip_count',1,'transit_id',transit,'trip_role','driver','payment_date',current_date,'description','Driver operating cost','payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',300))))),gen_random_uuid()) from payroll_context;
select pg_temp.payroll_check((public.get_transit_payroll(transit)->>'paid')::numeric=300,'trip employee payout allocation') from payroll_context;
select pg_temp.payroll_fails($q$select public.save_transit_costs(transit,'{"driver_cost":200,"helper_cost":200,"oil_cost":100,"others_cost":0}',3) from payroll_context$q$,'below employee payments');
select public.transition_transit(transit,'complete',3) from payroll_context;
select public.transition_transit(transit,'close',4) from payroll_context;
reset role;
select pg_temp.payroll_check((select -sum(amount) from public.wallet_transactions where type='transit_close_cost' and reference_id=(select transit from payroll_context))=500,'closure charges only unpaid 500 of total 800');
select pg_temp.payroll_check(not exists(select 1 from public.wallets w where tenant_id='e1111111-1111-4111-8111-111111111111' and balance<>opening_balance+coalesce((select sum(amount) from public.wallet_transactions x where x.tenant_id=w.tenant_id and x.wallet_id=w.wallet_id),0)),'wallet balance reconciles');
select pg_temp.payroll_check(not exists(select 1 from public.employee_payment_entries en left join public.wallet_transactions wt on wt.tenant_id=en.tenant_id and wt.employee_entry_id=en.entry_id where en.tenant_id='e1111111-1111-4111-8111-111111111111' and wt.transaction_id is null),'every payout entry has exactly one posting');
select pg_temp.payroll_fails($q$update public.employee_payments set amount=1 where tenant_id='e1111111-1111-4111-8111-111111111111'$q$,'immutable');
select pg_temp.payroll_fails($q$delete from public.payroll_adjustments where tenant_id='e1111111-1111-4111-8111-111111111111'$q$,'immutable');
set local role authenticated;
select set_config('request.jwt.claim.sub','f2222222-2222-4222-8222-222222222222',true);
select pg_temp.payroll_check((public.get_employee_directory()->>'total')::int=0,'foreign directory isolation');
select pg_temp.payroll_fails($q$select public.get_employee_profile(eid) from payroll_context$q$,'not found');
select pg_temp.payroll_fails($q$select public.payroll_operation(jsonb_set(body,'{items,1,payments,0,amount}','14000'),gen_random_uuid()) from payroll_context$q$,'not found');
select pg_temp.payroll_fails($q$select public.get_transit_payroll(transit) from payroll_context$q$,'not found');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','e2222222-2222-4222-8222-222222222222',true);
-- A current termination can take effect immediately with explicit preservation;
-- the already prepared current salary remains its original snapshot.
select public.payroll_operation(jsonb_build_object('action','prepare','employee_id',eid,'period',date_trunc('month',current_date)::date),gen_random_uuid()) from payroll_context;
select public.save_employee(jsonb_build_object('employee_id',eid,'revision',4,'name','Payroll Driver Mirpur','phones','[{"phone":"01700000031","is_primary":true}]'::jsonb,'business_unit','truck_business','terms',jsonb_build_object('effective_from',current_date,'monthly_salary',31000,'is_active',false,'reason','Current termination; prepared month reviewed','preserve_prepared',true)),gen_random_uuid()) from payroll_context;
select pg_temp.payroll_check((public.get_employee_profile(eid)->'employee'->>'is_active')::boolean=false and (public.get_employee_periods(eid)->'entries'->0->>'base_amount')::numeric=31000,'current termination preserves the prepared month') from payroll_context;
reset role;
delete from public.role_permissions where tenant_id='e1111111-1111-4111-8111-111111111111' and permission_id in ('payroll:pay','payroll:view');
set local role authenticated;
select set_config('request.jwt.claim.sub','e2222222-2222-4222-8222-222222222222',true);
select pg_temp.payroll_fails($q$select public.get_employee_activity()$q$,'Permission denied');
select pg_temp.payroll_fails($q$select public.payroll_operation('{}',gen_random_uuid())$q$,'Permission denied');
select pg_temp.payroll_check(public.get_employee_directory()->'entries'->0->'payroll'='null'::jsonb,'profile read does not leak payroll');
select 'PASS: payroll proration, employment changes, snapshots, salary revisions, partial/multi-wallet/multiple/bulk payments, advances, adjustments, reversals, idempotency, rollback, trip closure, ledger reconciliation, immutability and tenant/capability isolation';
rollback;
